import java.util.Scanner; public class Main { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (!sc.hasNextInt()) return; int t = sc.nextInt(); while (t-- > 0) { int n = sc.nextInt(); int m = sc.nextInt(); char[][] grid = new char[n][m]; for (int i = 0; i < n; i++) { String row = sc.next(); grid[i] = row.toCharArray(); } int maxBorder = 0; for (int i = 0; i < n; i++) { int current = 0; for (int j = 0; j < m; j++) { if (grid[i][j] == '#') { current++; maxBorder = Math.max(maxBorder, current); } else { current = 0; } } } for (int j = 0; j < m; j++) { int current = 0; for (int i = 0; i < n; i++) { if (grid[i][j] == '#') { current++; maxBorder = Math.max(maxBorder, current); } else { current = 0; } } } System.out.println(maxBorder); } sc.close(); } }